import 'package:get/get.dart';
import '../../data/models/journey_model.dart';
import '../../data/repositories/journey_repository.dart';
class JourneyController extends GetxController { JourneyController({JourneyRepository? repository}) : _repository=repository??JourneyRepository(); final JourneyRepository _repository; final journeys=<JourneyModel>[].obs; final isLoading=false.obs; JourneyModel? get activeJourney { for (final item in journeys) { if (item.status == 'Active') return item; } return null; } int get plannedCount => journeys.where((item) => item.status == 'Planned').length; @override void onInit(){super.onInit();load();} Future<void> load() async {isLoading.value=true;try{journeys.assignAll(await _repository.all());}finally{isLoading.value=false;}} Future<void> create(JourneyModel item) async {await _repository.create(item);await load();} Future<void> changeStatus(JourneyModel item,String status,{String? reason}) async {if(status == 'Active' && activeJourney != null && activeJourney!.id != item.id) throw StateError('Selesaikan perjalanan aktif terlebih dahulu.'); await _repository.updateStatus(item,status,reason:reason);await load();} }
